    for (i = 1; i < npk; i++) {          # insertion sort
        v = psort[i]; j = i - 1
        while (j >= 0 && psort[j] > v) { psort[j+1] = psort[j]; j-- }
        psort[j+1] = v
    }

    emitted = 0
    nr = 0
    for (i = 0; i < npk; i++)
        if (deg[psort[i]] + 0 == 0) ready[nr++] = psort[i]

