        p = ready[0]                     # smallest ready (byte order)
        for (i = 1; i < nr; i++) ready[i-1] = ready[i]
        nr--
        if (p in done) continue
        done[p] = 1
        print p
        emitted++
        # packages depending on p lose one pending dep
        for (q in deg)
            if (!(q in done) && (p SUBSEP q) in edge) {
                deg[q]--
                if (deg[q] == 0) {
                    ready[nr++] = q
                    for (i = nr - 1; i > 0 && ready[i-1] > q; i--) {
                        ready[i] = ready[i-1]; ready[i-1] = q
                    }
                }
            }
    }

    if (emitted < npk) {
        out = ""
        for (i = 0; i < npk; i++)
            if (!(psort[i] in done))
                out = out (out == "" ? "" : " ") psort[i]
        printf "cycle: %s\n", out > "/dev/stderr"
        exit 1
    }
    exit 0
}
