import re, heapq

def parse(fn):
    deps = {}
    pkgs = set()
    for line in open(fn):
        line = re.sub(r'#.*', '', line)
        if not line.strip():
            continue
        line = line.replace(':', ' ', 1)
        parts = line.split()
        pkg, ds = parts[0], parts[1:]
        pkgs.add(pkg)
        deps.setdefault(pkg, set()).update(ds)
        pkgs.update(ds)
    return pkgs, {p: {d for d in deps.get(p, set()) if d != p} for p in pkgs}

def expected(fn):
    pkgs, deps = parse(fn)
    ready = [p for p in pkgs if not deps[p]]
    heapq.heapify(ready)
    done = set(); order = []
    while ready:
        p = heapq.heappop(ready)
        if p in done: continue
        done.add(p); order.append(p)
        for q in pkgs:
            if q not in done and p in deps[q]:
                deps[q].discard(p)
                if not deps[q]:
                    heapq.heappush(ready, q)
    return order, sorted(pkgs - done)

for fn in ('deps.txt', 'deps-big.txt', 'deps-cycle.txt'):
    order, cyc = expected(fn)
    print(fn, '->', ' '.join(order), '| cycle:', cyc)
EOF

